package vpn

import (
	"cuhk-vpn-go/internal/config"
	"cuhk-vpn-go/internal/platform"
	"fmt"
	"net/netip"
	"os"
	"path/filepath"
	"runtime"
	"strings"
)

func routeParts(cidr string) (string, string, int) {
	p := netip.MustParsePrefix(cidr)
	n := uint32(0xffffffff) << (32 - p.Bits())
	return p.Addr().String(), fmt.Sprintf("%d.%d.%d.%d", byte(n>>24), byte(n>>16), byte(n>>8), byte(n)), p.Bits()
}

// Scripts are generated by the privileged helper in its own private directory.
// The installed official scripts are never modified.
func WriteScripts(dir, official string, s config.Settings) (string, string, error) {
	marker := filepath.Join(dir, "tunnel-state")
	name := "split-vpnc.sh"
	body := UnixScript(official, marker, s)
	if runtime.GOOS == "windows" {
		b, e := os.ReadFile(official)
		if e != nil {
			return "", "", e
		}
		// Avoid console flashes from the stock script's WshShell.Exec children.
		if strings.Count(string(b), "ws.Exec(fullCmd)") != 2 {
			return "", "", fmt.Errorf("当前 Windows 官方脚本版本不受支持，请使用 OpenConnect 9.21")
		}
		managed := filepath.Join(dir, "vpnc-managed.js")
		text := strings.ReplaceAll(string(b), "ws.Exec(fullCmd)", "cuhkHiddenExec(cmd)")
		for _, command := range []string{`run("route add " + vpngw + " mask 255.255.255.255 " + gw4);`, `run("route delete " + vpngw + " mask 255.255.255.255");`} {
			if strings.Count(text, command) != 1 {
				return "", "", fmt.Errorf("官方路由脚本的网关管理方式不受支持")
			}
			text = strings.Replace(text, command, `if (env("CUHK_VPN_MANAGED_GATEWAY") != vpngw) `+command, 1)
		}
		if e = os.WriteFile(managed, []byte(hiddenRunner+text), 0600); e != nil {
			return "", "", e
		}
		body = WindowsScript(managed, marker, s)
		name = "split-vpnc.js"
	}
	p := filepath.Join(dir, name)
	e := os.WriteFile(p, []byte(body), 0700)
	return p, marker, e
}
func UnixScript(official, marker string, s config.Settings) string {
	var b strings.Builder
	b.WriteString("#!/bin/sh\n# Generated split tunnel wrapper. Only the configured IPv4 prefixes are allowed.\n")
	b.WriteString("export INTERNAL_IP4_NETMASK=255.255.255.255\nexport INTERNAL_IP4_NETMASKLEN=32\nexport INTERNAL_IP4_NETADDR=\"$INTERNAL_IP4_ADDRESS\"\n")
	fmt.Fprintf(&b, "export CISCO_SPLIT_INC=%d\nexport CISCO_SPLIT_EXC=0\nexport CISCO_IPV6_SPLIT_INC=0\nexport CISCO_IPV6_SPLIT_EXC=0\nunset INTERNAL_IP6_ADDRESS INTERNAL_IP6_NETMASK INTERNAL_IP6_DNS\n", len(s.CIDRs))
	for i, c := range s.CIDRs {
		a, m, n := routeParts(c)
		fmt.Fprintf(&b, "export CISCO_SPLIT_INC_%d_ADDR=%s\nexport CISCO_SPLIT_INC_%d_MASK=%s\nexport CISCO_SPLIT_INC_%d_MASKLEN=%d\nexport CISCO_SPLIT_INC_%d_PROTOCOL=0\n", i, a, i, m, i, n, i)
	}
	if !s.KeepDNS {
		b.WriteString("unset INTERNAL_IP4_DNS INTERNAL_IP4_NBNS CISCO_DEF_DOMAIN CISCO_SPLIT_DNS\n")
	}
	fmt.Fprintf(&b, "/bin/sh %s \"$@\"\nresult=$?\nif [ \"$result\" -eq 0 ]; then\n  printf '%%s|%%s|%%s' \"$reason\" \"$INTERNAL_IP4_ADDRESS\" \"$TUNDEV\" > %s\nfi\nexit \"$result\"\n", platform.ShellQuote(official), platform.ShellQuote(marker))
	return b.String()
}
func jsQuote(s string) string {
	return "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"", "\r", "\\r", "\n", "\\n").Replace(s) + "\""
}
func WindowsScript(official, marker string, s config.Settings) string {
	var b strings.Builder
	b.WriteString("// Generated for Windows JScript (ES3).\nvar ws=WScript.CreateObject('WScript.Shell');\nvar env=ws.Environment('Process');\n")
	b.WriteString("env('INTERNAL_IP4_NETMASK')='255.255.255.255';\nenv('INTERNAL_IP4_NETMASKLEN')='32';\nenv('INTERNAL_IP4_NETADDR')=env('INTERNAL_IP4_ADDRESS');\n")
	fmt.Fprintf(&b, "env('CISCO_SPLIT_INC')='%d';\nenv('CISCO_SPLIT_EXC')='0';\nenv('CISCO_IPV6_SPLIT_INC')='0';\nenv('CISCO_IPV6_SPLIT_EXC')='0';\nenv('INTERNAL_IP6_ADDRESS')='';\nenv('INTERNAL_IP6_DNS')='';\n", len(s.CIDRs))
	for i, c := range s.CIDRs {
		a, m, n := routeParts(c)
		fmt.Fprintf(&b, "env('CISCO_SPLIT_INC_%d_ADDR')='%s';\nenv('CISCO_SPLIT_INC_%d_MASK')='%s';\nenv('CISCO_SPLIT_INC_%d_MASKLEN')='%d';\nenv('CISCO_SPLIT_INC_%d_PROTOCOL')='0';\n", i, a, i, m, i, n, i)
	}
	if !s.KeepDNS {
		b.WriteString("env('INTERNAL_IP4_DNS')='';\nenv('INTERNAL_IP4_NBNS')='';\nenv('CISCO_DEF_DOMAIN')='';\nenv('CISCO_SPLIT_DNS')='';\n")
	}
	fmt.Fprintf(&b, `var code=ws.Run('"'+WScript.FullName+'" //NoLogo "'+%s+'"',0,true);
if(code==0){var f=WScript.CreateObject('Scripting.FileSystemObject').CreateTextFile(%s,true);f.Write(env('reason')+'|'+env('INTERNAL_IP4_ADDRESS')+'|'+env('TUNDEV'));f.Close();}
WScript.Quit(code);
`, jsQuote(official), jsQuote(marker))
	return b.String()
}

const hiddenRunner = `function cuhkHiddenExec(cmd) {
 var files=WScript.CreateObject("Scripting.FileSystemObject");
 var outputPath=files.BuildPath(files.GetSpecialFolder(2),files.GetTempName());
 var reader=null,created=false;
 try {
  var output=files.CreateTextFile(outputPath,false);output.Close();created=true;
  var command='"'+comspec+'" /D /S /C "chcp 65001 >NUL & ('+cmd+') >"'+outputPath+'" 2>&1"';
  var code=ws.Run(command,0,true);
  reader=WScript.CreateObject("ADODB.Stream");reader.Type=2;reader.Charset="utf-8";reader.Open();reader.LoadFromFile(outputPath);
  var text=reader.ReadText();
  return {StdIn:{Close:function(){}},StdOut:{ReadAll:function(){return text;}},ExitCode:code};
 }finally{if(reader!=null)reader.Close();if(created&&files.FileExists(outputPath))files.DeleteFile(outputPath);}
}
`
